import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"ControlNet 入门","description":"解释 ControlNet 的条件控制原理、常见条件类型、预处理与权重用法，并区分它与提示词、LoRA、IP-Adapter 的分工。","frontmatter":{"description":"解释 ControlNet 的条件控制原理、常见条件类型、预处理与权重用法，并区分它与提示词、LoRA、IP-Adapter 的分工。"},"headers":[],"relativePath":"concepts/controlnet.md","filePath":"concepts/controlnet.md","lastUpdated":1788702042000}'),l={name:"concepts/controlnet.md"};function n(i,t,s,d,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="controlnet-入门" tabindex="-1">ControlNet 入门 <a class="header-anchor" href="#controlnet-入门" aria-label="Permalink to &quot;ControlNet 入门&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> ControlNet 是挂在扩散模型外部的条件控制器：把一张线稿、深度图或姿势骨架图编码成额外条件注入去噪过程，让“结构怎么摆”由参考图精确决定——提示词管“画什么”，它管“怎么摆”。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>读过 <a href="/concepts/components">AI 绘画由哪些部分组成</a> 会更顺，知道 ControlNet 在流水线的去噪阶段注入约束即可。</li><li>读过 <a href="/concepts/how-it-works">基本原理</a>，知道生成是“从噪声逐步去噪”的过程。</li><li>不要求训练经验：本页讲原理与使用思路，不含训练代码和调参教程。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>解释 ControlNet 解决什么问题，以及为什么提示词难以精确控制构图。</li><li>区分 ControlNet 与提示词、LoRA、IP-Adapter（把参考图的风格或内容注入生成的适配器）各自控制的对象。</li><li>说出常见条件类型（线稿、深度、姿势等）各自的用途。</li><li>知道“预处理”是什么、为什么条件图要先提取。</li><li>会用权重和介入阶段两个旋钮控制约束的强弱。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="它解决什么问题-提示词管不了-怎么摆" tabindex="-1">它解决什么问题：提示词管不了“怎么摆” <a class="header-anchor" href="#它解决什么问题-提示词管不了-怎么摆" aria-label="Permalink to &quot;它解决什么问题：提示词管不了“怎么摆”&quot;">​</a></h3><p>提示词擅长描述内容与风格，但空间关系靠文字很难精确：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提示词写法：“两个人面对面握手，一人站在画面左侧，一人站在右侧”</span></span>
<span class="line"><span>实际生成：站位随机、手部崩坏、背对背、多出一个人——都是概率问题</span></span></code></pre></div><p>原因在<a href="/concepts/how-it-works">基本原理</a>讲过：生成是从噪声逐步去噪，文字条件影响的是每一步的概率走向，“谁站在哪”这种像素级布局，文字的约束力很弱。</p><p>ControlNet 的思路是给去噪过程再加一条输入线：把一张“结构说明书”（线稿、深度图、骨架图）与提示词同时注入。提示词继续管内容与风格，这张图管构图与姿势——各管各的维度，互不替代。</p><h3 id="工作原理的直觉-给去噪网络外挂一个-读图员" tabindex="-1">工作原理的直觉：给去噪网络外挂一个“读图员” <a class="header-anchor" href="#工作原理的直觉-给去噪网络外挂一个-读图员" aria-label="Permalink to &quot;工作原理的直觉：给去噪网络外挂一个“读图员”&quot;">​</a></h3><p>ControlNet 本身是一个训练出来的神经网络：用海量“图片 + 对应条件图”的成对数据训练，让它学会读各种结构说明书。使用时它的输出接到底模去噪网络的中间层，与提示词的注入并列生效；接入处的新增连接从零开始训练，底模原有能力不受影响。</p><p>训练时用的是反向思路：故意把图片破坏成线稿、深度图或骨架图，让模型学会“照着这份残缺信息补全完整图片”。用的时候顺理成章——你给它线稿，它就照线稿补全。</p><h3 id="常见条件类型-一类-说明书-管一个维度" tabindex="-1">常见条件类型：一类“说明书”管一个维度 <a class="header-anchor" href="#常见条件类型-一类-说明书-管一个维度" aria-label="Permalink to &quot;常见条件类型：一类“说明书”管一个维度&quot;">​</a></h3><ul><li><strong>线稿 / 边缘</strong>（Canny、Lineart、Soft Edge）：留住轮廓与结构线。适合把草图变成品图、保持外形换画风。</li><li><strong>深度图</strong>（Depth）：记录远近层次与体积。适合从照片转绘、保持构图重绘内容。</li><li><strong>姿势骨架</strong>（OpenPose）：把人物提炼成火柴人骨架，只管动作与站位，不管外形。适合精准摆人物。</li><li><strong>涂鸦</strong>（Scribble）：随手几笔的粗略轮廓也能被读懂。适合快速起稿。</li><li><strong>降质图 / 平铺</strong>（Blur、Tile）：拿模糊或局部图当条件，常用于放大与细节修补。</li></ul><p>同一张参考图通常不能直接用——它要先经“预处理”变成对应类型的条件图。</p><h3 id="预处理-先提取-说明书-再交给-controlnet" tabindex="-1">预处理：先提取“说明书”，再交给 ControlNet <a class="header-anchor" href="#预处理-先提取-说明书-再交给-controlnet" aria-label="Permalink to &quot;预处理：先提取“说明书”，再交给 ControlNet&quot;">​</a></h3><p>把参考图加工成条件图的步骤叫预处理（Preprocessor）：真人照片先经 OpenPose 提取骨架，风景照先提取深度图，草稿先跑 Canny 提取边缘。工具里有现成的预处理节点，通常与 ControlNet 节点成对出现。</p><p>为什么不直接喂原图？预处理把“要控制的维度”提纯出来：只要姿势，就别把照片里的画风、光影、背景一起带进来。条件越纯粹，控制越精准，提示词剩下的自由度也越大。</p><h3 id="权重与介入阶段-两个强弱旋钮" tabindex="-1">权重与介入阶段：两个强弱旋钮 <a class="header-anchor" href="#权重与介入阶段-两个强弱旋钮" aria-label="Permalink to &quot;权重与介入阶段：两个强弱旋钮&quot;">​</a></h3><ul><li><strong>权重（strength）</strong>：0 等于不生效。结构必须严格贴合时从 0.8 到 1.0 起试；过高会挤压提示词的发挥，画面趋向“照描”条件图。</li><li><strong>介入阶段（start / end）</strong>：可以只在前期介入——构图成形后放开，让提示词在后期细化细节。“前期管结构、后期还自由”是常用组合。</li></ul><h2 id="最小推演-摆一个提示词摆不出的画面" tabindex="-1">最小推演：摆一个提示词摆不出的画面 <a class="header-anchor" href="#最小推演-摆一个提示词摆不出的画面" aria-label="Permalink to &quot;最小推演：摆一个提示词摆不出的画面&quot;">​</a></h2><p>任务：画“两个面对面握手的人”。先只写提示词生成几次：站位与手部大概率不稳定——这是文字条件的天然短板。</p><p>用 ControlNet 的流程：</p><ol><li>找一张双人握手参考图，或直接用现成的双人骨架图。</li><li>经 OpenPose 预处理提取骨架：站位、朝向、握手的位置就此定死。</li><li>骨架图接入 ControlNet，权重 1.0，全程介入。</li><li>提示词只管衣着、场景、风格：“两个穿大衣的男人握手，雪夜街头”。</li><li>生成对照：站位与骨架一致；想换姿势，换一张骨架图即可，提示词一个字不用改。</li></ol><p>这个推演只说明“结构交给条件图、内容交给提示词”的分工，不代表一次就能出完美结果——手部等细节仍可能需要多次重抽或局部重绘。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>想精确控制画面时，四种手段控制的对象完全不同：</p><table tabindex="0"><thead><tr><th>维度</th><th>提示词</th><th>LoRA</th><th>IP-Adapter</th><th>ControlNet</th></tr></thead><tbody><tr><td>控制对象</td><td>内容、风格、质量</td><td>补充概念、画风</td><td>参考图的风格或内容</td><td>结构、构图、姿势</td></tr><tr><td>输入</td><td>文字</td><td>模型文件</td><td>参考图</td><td>预处理后的条件图</td></tr><tr><td>控制精度</td><td>模糊（概率性）</td><td>中（概念级）</td><td>中低（气质级）</td><td>高（像素级结构）</td></tr><tr><td>典型用途</td><td>描述画面</td><td>固定角色、画风</td><td>风格迁移、参考变体</td><td>精准摆位、草图成品化</td></tr></tbody></table><p>一句话分工：提示词管“画什么”，LoRA 管“多会画什么”，IP-Adapter 管“像这张的气质”，ControlNet 管“结构怎么摆”。实践中常组合使用：ControlNet 定结构，提示词填内容，LoRA 固定角色。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“ControlNet 是更强的提示词”</strong>：它不负责决定“画什么”，只按条件图约束结构；画什么仍要靠提示词描述。</li><li><strong>“随便丢一张照片就能控制”</strong>：多数条件类型要先经预处理提取对应的条件图；类型不配套（线稿模型配了深度图）控制就会失效。</li><li><strong>“权重拉满最听话”</strong>：过高会挤压提示词的自由度，画面趋向照描；只有结构必须严格贴合时才用高权重。</li><li><strong>“ControlNet 跨底模通用”</strong>：与 LoRA 一样分生态，SD1.5、SDXL 与 FLUX 等新一代模型各有各的控制方案，选型看模型页标注与底模匹配（见<a href="/models/ecosystems">常见模型生态</a>）。</li><li><strong>“结构定住就不用管提示词了”</strong>：结构只是骨架，内容、风格、质量仍靠提示词与采样参数；两者是分工，不是替代。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-提示词写-一人站左侧、一人站右侧-总是画不对-controlnet-为什么能解决" tabindex="-1">1. 提示词写“一人站左侧、一人站右侧”总是画不对，ControlNet 为什么能解决？ <a class="header-anchor" href="#_1-提示词写-一人站左侧、一人站右侧-总是画不对-controlnet-为什么能解决" aria-label="Permalink to &quot;1. 提示词写“一人站左侧、一人站右侧”总是画不对，ControlNet 为什么能解决？&quot;">​</a></h3><details><summary>查看答案</summary><p>站位布局是像素级的结构信息，文字条件只能以概率方式影响去噪走向，约束力弱。ControlNet 把结构作为额外条件直接注入去噪过程，骨架图先把站位定死，模型按条件补全画面，文字只需管内容与风格。</p></details><h3 id="_2-用真人照片控制人物姿势-为什么不把照片直接接进-controlnet" tabindex="-1">2. 用真人照片控制人物姿势，为什么不把照片直接接进 ControlNet？ <a class="header-anchor" href="#_2-用真人照片控制人物姿势-为什么不把照片直接接进-controlnet" aria-label="Permalink to &quot;2. 用真人照片控制人物姿势，为什么不把照片直接接进 ControlNet？&quot;">​</a></h3><details><summary>查看答案</summary><p>ControlNet 吃的是特定类型的条件图，照片要先经 OpenPose 预处理提取骨架。预处理把“姿势”这一个维度提纯出来，避免照片里的画风、光影和背景混进控制信号——条件越纯粹，控制越精准，提示词越自由。</p></details><h3 id="_3-controlnet、lora、ip-adapter-同时使用时-各管什么" tabindex="-1">3. ControlNet、LoRA、IP-Adapter 同时使用时，各管什么？ <a class="header-anchor" href="#_3-controlnet、lora、ip-adapter-同时使用时-各管什么" aria-label="Permalink to &quot;3. ControlNet、LoRA、IP-Adapter 同时使用时，各管什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>ControlNet 管结构与构图（条件图输入），LoRA 管固定角色或画风概念（模型文件输入），IP-Adapter 迁移参考图的气质与风格（参考图输入）。三者作用维度不同、互不替代，可以叠加；叠加时建议一次只调一个，方便归因。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>前置概念：</strong> <a href="/concepts/components">AI 绘画由哪些部分组成</a>说明 ControlNet 在流水线中注入的位置与部件分工。</li><li><strong>同主题：</strong> <a href="/lora/basics">LoRA 入门</a>讲另一类附件：管“多会画什么”，而不是“结构怎么摆”。</li><li><strong>进阶实操：</strong> <a href="/resources/tutorials">精选教程</a>收录 ComfyUI 官方 ControlNet 教程，跟着跑通第一个可控构图工作流。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">ControlNet 论文</a>：条件控制注入扩散模型的原始论文。</li><li><a href="https://github.com/lllyasviel/ControlNet" target="_blank" rel="noreferrer">ControlNet 官方仓库</a>：官方代码与条件类型说明。</li><li><a href="https://docs.comfy.org/zh/tutorials/controlnet/controlnet" target="_blank" rel="noreferrer">ComfyUI 官方 ControlNet 教程</a>：在 ComfyUI 中使用 ControlNet 的官方中文教程。</li><li><a href="https://github.com/CMU-Perceptual-Computing-Lab/openpose" target="_blank" rel="noreferrer">OpenPose 官方仓库</a>：姿势骨架提取的原始项目。</li></ul>`,46)])])}const b=o(l,[["render",n]]);export{u as __pageData,b as default};
